import{_ as c,C as a,o as i,c as r,ak as e,E as o}from"./chunks/framework.DxrHb2fb.js";const p=JSON.parse('{"title":"动效","description":"","frontmatter":{},"headers":[],"relativePath":"design/motion.md","filePath":"design/motion.md","lastUpdated":1790420182000}'),n={name:"design/motion.md"};function l(s,t,h,m,g,x){const d=a("XhTokenTable");return i(),r("div",null,[t[0]||(t[0]=e('<h1 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h1><p>动效只做四件事：确认操作、交代去向、提示进行中与变化，以及在极少数情况下引导注意。全库动效归为下面的角色，组件只选择角色，不自定时长、缓动与幅度；时长、曲线与幅度全部是令牌，关键帧集中在 <code>family/motion.css</code>，皮肤只引用。</p><h2 id="角色" tabindex="-1">角色 <a class="header-anchor" href="#角色" aria-label="Permalink to &quot;角色&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>用途</th><th>可动属性</th><th>时长 / 缓动</th><th>减弱动效</th></tr></thead><tbody><tr><td>按压</td><td>确认按下</td><td><code>scale</code> + 换面</td><td><code>press</code> / <code>press</code>，<code>release</code> / <code>release</code></td><td>只换面</td></tr><tr><td>状态</td><td>hover、选中、焦点、校验的换色</td><td>颜色、描边色、阴影、<code>opacity</code></td><td><code>micro</code> / <code>enter</code></td><td>保留淡变</td></tr><tr><td>切换</td><td>开关滑块、单选圆点、勾选标记</td><td><code>translate</code>、<code>scale</code></td><td><code>nudge</code> / <code>continuous</code>；短边不超过 32px 的缩放可用 <code>settle</code></td><td>瞬时</td></tr><tr><td>指示</td><td>选中指示器在项之间移动</td><td><code>translate</code>；尺寸为登记例外</td><td><code>move</code> / <code>continuous</code></td><td>瞬时</td></tr><tr><td>披露</td><td>内容展开收起</td><td><code>grid-template-rows</code></td><td><code>expand</code> / <code>enter-strong</code>；<code>collapse</code> / <code>exit</code></td><td>瞬时</td></tr><tr><td>出现</td><td>挂载与卸载</td><td><code>opacity</code>、小幅 <code>translate</code> / <code>scale</code></td><td><code>enter</code> / <code>enter</code> 或 <code>enter-strong</code>；<code>exit</code> / <code>exit</code></td><td>淡变</td></tr><tr><td>列表</td><td>加入、移除、重排、错开</td><td>同出现；重排用 <code>translate</code></td><td>同出现；重排 <code>move</code> / <code>continuous</code></td><td>淡变，无错开</td></tr><tr><td>导航</td><td>抽屉、侧栏、走马灯、标签带滚动、平滑滚动</td><td><code>translate</code>、滚动位置</td><td>进 <code>slide</code> / <code>slide</code>；出 <code>exit</code> / <code>exit</code></td><td>抽屉类淡变，其余瞬时</td></tr><tr><td>数值</td><td>进度、计数、倒计时</td><td><code>translate</code>、<code>clip-path</code>、文本</td><td><code>move</code> / <code>continuous</code></td><td>瞬时；倒计时按秒分段</td></tr><tr><td>手势</td><td>拖拽跟手、松手归位、快甩、越界回弹</td><td><code>translate</code>、<code>scale</code></td><td>跟手无过渡；松手用弹簧并交接松手速度</td><td>瞬时归位</td></tr><tr><td>循环</td><td>转圈、微光、光标、不定进度、呼吸</td><td><code>rotate</code>、<code>background-position</code>、<code>opacity</code>、<code>translate</code></td><td>循环周期 / <code>loop</code></td><td>停止并显示静态替代</td></tr><tr><td>注意</td><td>抖动、脉冲强调</td><td>—</td><td>只在 <a href="/guide/animations"><code>@xihan-ui/animations</code></a> 中使用：<code>attention</code></td><td>不播放</td></tr><tr><td>数据</td><td>图表入场、更新、退出</td><td>几何参数、<code>stroke-dashoffset</code>、<code>opacity</code></td><td>入场 <code>reveal</code> / <code>enter-strong</code>，描线 <code>reveal</code> / <code>continuous</code>；更新 <code>morph</code> / <code>continuous</code>；淡入 <code>enter</code></td><td>几何瞬时，淡变保留</td></tr><tr><td>氛围</td><td>动态背景、跑马灯</td><td>着色器时间轴、<code>translate</code></td><td>由速度决定</td><td>冻结或停止</td></tr></tbody></table><p>表中时长省略前缀 <code>--xh-motion-duration-</code>，缓动省略前缀 <code>--xh-motion-ease-</code>。</p><ul><li>带位移、缩放、旋转或尺寸变化的动画不用 <code>micro</code>、<code>enter</code>、<code>exit</code> 三支时长：这三支在减弱动效下保留为淡变。例外是进出场（出现、列表加入与移除、整幅滑出）：其中的位移与缩放只取幅度令牌，减弱动效下归零，剩下的只有淡变，所以照常取 <code>enter</code> / <code>exit</code>。</li><li><code>move</code> 与 <code>nudge</code> 的分界：跨位置的换位与尺寸变化（指示器滑移、进度增长、堆叠重排、视口长高）取 <code>move</code>；原地的小幅几何变化（滑块、勾选标记、展开箭头、拇指缩放）与跟手的让位、查看器缩放平移取 <code>nudge</code>。</li></ul><h2 id="令牌" tabindex="-1">令牌 <a class="header-anchor" href="#令牌" aria-label="Permalink to &quot;令牌&quot;">​</a></h2><h3 id="时长" tabindex="-1">时长 <a class="header-anchor" href="#时长" aria-label="Permalink to &quot;时长&quot;">​</a></h3><table tabindex="0"><thead><tr><th>令牌</th><th style="text-align:right;">取值</th><th style="text-align:right;">减弱动效</th><th>角色</th></tr></thead><tbody><tr><td><code>--xh-motion-duration-micro</code></td><td style="text-align:right;">120ms</td><td style="text-align:right;">120ms</td><td>状态</td></tr><tr><td><code>--xh-motion-duration-enter</code></td><td style="text-align:right;">200ms</td><td style="text-align:right;">120ms</td><td>出现、列表加入</td></tr><tr><td><code>--xh-motion-duration-exit</code></td><td style="text-align:right;">120ms</td><td style="text-align:right;">120ms</td><td>出现、列表移除、导航出</td></tr><tr><td><code>--xh-motion-duration-move</code></td><td style="text-align:right;">200ms</td><td style="text-align:right;">1ms</td><td>指示、列表重排、数值</td></tr><tr><td><code>--xh-motion-duration-expand</code></td><td style="text-align:right;">200ms</td><td style="text-align:right;">1ms</td><td>披露展开</td></tr><tr><td><code>--xh-motion-duration-collapse</code></td><td style="text-align:right;">120ms</td><td style="text-align:right;">1ms</td><td>披露收起</td></tr><tr><td><code>--xh-motion-duration-slide</code></td><td style="text-align:right;">320ms</td><td style="text-align:right;">1ms</td><td>导航进</td></tr><tr><td><code>--xh-motion-duration-nudge</code></td><td style="text-align:right;">120ms</td><td style="text-align:right;">1ms</td><td>切换、跟手让位</td></tr><tr><td><code>--xh-motion-duration-press</code> / <code>-release</code></td><td style="text-align:right;">120 / 200ms</td><td style="text-align:right;">1ms</td><td>按压</td></tr><tr><td><code>--xh-motion-duration-attention</code></td><td style="text-align:right;">640ms</td><td style="text-align:right;">1ms（预设不播）</td><td>注意</td></tr><tr><td><code>--xh-motion-duration-reveal</code></td><td style="text-align:right;">640ms</td><td style="text-align:right;">1ms</td><td>数据首次出现</td></tr><tr><td><code>--xh-motion-duration-morph</code></td><td style="text-align:right;">400ms</td><td style="text-align:right;">1ms</td><td>数据更新</td></tr><tr><td><code>--xh-motion-stagger-step</code></td><td style="text-align:right;">40ms</td><td style="text-align:right;">0ms</td><td>错开步长</td></tr></tbody></table><p>几何类在减弱动效下取 1ms 而不是 0：动画名照常变化、<code>animationend</code> 照常派发，进出场的时序不分叉。</p><p>循环周期不降级，减弱动效下由皮肤停掉动画、换成静态替代：</p>',11)),o(d,{names:["--xh-motion-loop-spin","--xh-motion-loop-caret","--xh-motion-loop-shimmer","--xh-motion-loop-breathe"],notes:{"--xh-motion-loop-spin":"旋转指示器转一圈","--xh-motion-loop-caret":"文本光标闪一次","--xh-motion-loop-shimmer":"骨架屏与在跑文字的微光扫过一遍","--xh-motion-loop-breathe":"进行中状态点的一次呼吸"}}),t[1]||(t[1]=e('<h3 id="缓动" tabindex="-1">缓动 <a class="header-anchor" href="#缓动" aria-label="Permalink to &quot;缓动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>令牌</th><th>原语</th><th>用途</th></tr></thead><tbody><tr><td><code>--xh-motion-ease-continuous</code></td><td><code>standard</code></td><td>在屏内被推到新位置：指示器、重排、数值</td></tr><tr><td><code>--xh-motion-ease-loop</code></td><td><code>linear</code></td><td>匀速的无限循环</td></tr><tr><td><code>--xh-motion-ease-enter</code></td><td><code>out</code></td><td>淡入与换色</td></tr><tr><td><code>--xh-motion-ease-enter-strong</code></td><td><code>out-strong</code></td><td>带位移的入场、展开、原地形变</td></tr><tr><td><code>--xh-motion-ease-exit</code></td><td><code>in</code></td><td>退场、收起</td></tr><tr><td><code>--xh-motion-ease-slide</code></td><td><code>out-fluid</code></td><td>整幅位移：抽屉推入、轮播换页</td></tr><tr><td><code>--xh-motion-ease-sweep</code></td><td><code>in-out</code></td><td>往返型循环的折返</td></tr><tr><td><code>--xh-motion-ease-press</code> / <code>-release</code></td><td><code>standard</code> / <code>out-strong</code></td><td>按压时间线</td></tr><tr><td><code>--xh-motion-ease-settle</code></td><td><code>out-back</code></td><td>短边不超过 32px 的小件过冲落位</td></tr><tr><td><code>--xh-motion-ease-breathe</code></td><td><code>sine-in-out</code></td><td>呼吸</td></tr><tr><td><code>--xh-motion-ease-emphasis</code></td><td><code>emphasized</code></td><td><code>@xihan-ui/animations</code> 的表现性进场，组件皮肤不用</td></tr></tbody></table><p>缓动不降级：曲线形状不引起前庭不适，减弱动效靠时长与幅度收敛。原语：</p>',3)),o(d,{names:["--xh-ease-standard","--xh-ease-in","--xh-ease-out","--xh-ease-out-strong","--xh-ease-out-fluid","--xh-ease-in-out","--xh-ease-out-back","--xh-ease-sine-in-out","--xh-ease-emphasized"]}),t[2]||(t[2]=e('<h3 id="幅度" tabindex="-1">幅度 <a class="header-anchor" href="#幅度" aria-label="Permalink to &quot;幅度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>令牌</th><th style="text-align:right;">取值</th><th style="text-align:right;">减弱动效</th><th>用途</th></tr></thead><tbody><tr><td><code>--xh-motion-distance-sm</code> / <code>-md</code></td><td style="text-align:right;">4 / 8px</td><td style="text-align:right;">0</td><td>浮层滑入、面板与列表条目入场</td></tr><tr><td><code>--xh-motion-distance-lg</code></td><td style="text-align:right;">16px</td><td style="text-align:right;">0</td><td><code>@xihan-ui/animations</code> 的表现性进场</td></tr><tr><td><code>--xh-motion-travel</code></td><td style="text-align:right;">100%</td><td style="text-align:right;">0</td><td>整幅位移：抽屉、轻提示</td></tr><tr><td><code>--xh-motion-travel-opacity</code></td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td>整幅位移两端的不透明度：减弱动效下位移归零，改由淡变表达</td></tr><tr><td><code>--xh-motion-scale-enter</code> / <code>-exit</code></td><td style="text-align:right;">0.96 / 0.98</td><td style="text-align:right;">1</td><td>出现</td></tr><tr><td><code>--xh-motion-scale-press</code></td><td style="text-align:right;">0.97</td><td style="text-align:right;">1</td><td>按压</td></tr><tr><td><code>--xh-motion-scale-drag</code></td><td style="text-align:right;">1.12</td><td style="text-align:right;">1</td><td>拖起</td></tr><tr><td><code>--xh-motion-scale-stack</code></td><td style="text-align:right;">0.95</td><td style="text-align:right;">1</td><td>轻提示叠放每往后一层的收拢比例</td></tr><tr><td><code>--xh-motion-scale-squash</code></td><td style="text-align:right;">0.86</td><td style="text-align:right;">1</td><td>liquid 档指示器拉长时另一向的压扁下限</td></tr><tr><td><code>--xh-motion-scale-breathe</code> / <code>-halo</code></td><td style="text-align:right;">0.82 / 2.6</td><td style="text-align:right;">1</td><td>呼吸的吸气最小值与光环外扩</td></tr></tbody></table><p>组件不自设缩放与位移的字面量。JS 侧 <code>@xihan-ui/motion</code> 的 <code>motionDurations</code>、<code>motionEasings</code>、<code>motionDistances</code>、<code>motionStaggerStep</code> 与弹簧预设和令牌逐条对账（门禁 <code>check-motion-source</code>）；读得到计算样式时以 <code>readMotion(el)</code> 为准，作者对组件槽的覆盖与容器上的 <code>data-motion</code> 同时生效。</p><h2 id="编排" tabindex="-1">编排 <a class="header-anchor" href="#编排" aria-label="Permalink to &quot;编排&quot;">​</a></h2><ul><li><strong>进出不对称</strong>：进场比退场长一档（<code>enter</code> 200ms、<code>exit</code> 120ms），进场减速、退场加速；退场是让路。</li><li><strong>方向</strong>：从哪来回哪去——锚定浮层从锚点一侧滑出，抽屉从所在边推入，轻提示从视口边缘进出；RTL 下横向位移随书写方向翻转。</li><li><strong>错开</strong>：只对同一批到达的条目按到达顺序计数，步长 <code>--xh-motion-stagger-step</code>，最多 5 步，后面的与第 5 步同时出现；不按 DOM 位置（<code>nth-child</code>）计数。每次都是同一批一起露面的（浮动按钮列表、级联列、问答选项）位次就是到达顺序。</li><li><strong>分层</strong>：遮罩与面板同时开始、同时退场，在最长的那个结束后卸载；面板内列表的错开从面板进场开始计时。</li><li><strong>首帧不播进场</strong>：初始渲染时已存在的内容（默认展开的披露、默认打开的浮层、历史消息、初始列表）直接呈现，只有用户操作或新数据带来的出现才播进场。Headless 以 <code>data-instant</code> 标记这类内容，皮肤把进场写在 <code>:not([data-instant])</code> 下；标记挂在条目上，只有它自己变了才撤，撤掉祖先上的标记会让下面所有静止的元素同时重播进场。</li><li><strong>打断与反转</strong>：退场中途重新打开时取消退场，从当前透明度继续进场，不先跳回不可见；换位中途再换，从当前位置接着走。</li><li><strong>焦点与事件</strong>：进场开始即移入焦点，退场开始即归还；退场中的节点不可命中、不接收键盘；业务回调不等待动画。</li><li><strong>不闪</strong>：任意一秒内明暗交替不超过三次（WCAG 2.3.1）。皮肤里的 CSS 动画由门禁 <code>check-attention-flash</code> 核，<code>@xihan-ui/animations</code> 的配方在播放入口按同一套数法校验。</li></ul><h2 id="按压触感" tabindex="-1">按压触感 <a class="header-anchor" href="#按压触感" aria-label="Permalink to &quot;按压触感&quot;">​</a></h2><p>定尺的独立动作控件（按钮、把手、方框、星、日历格、色块、排序钮）投影 Action Control 配方，按下与释放走同一条时间线：</p><table tabindex="0"><thead><tr><th>阶段</th><th style="text-align:right;">时长</th><th>结果</th><th>缓动</th></tr></thead><tbody><tr><td>按下</td><td style="text-align:right;">120ms（<code>--xh-motion-duration-press</code>）</td><td>scale 1 → 0.97，底进入 active</td><td><code>--xh-motion-ease-press</code></td></tr><tr><td>释放</td><td style="text-align:right;">200ms（<code>--xh-motion-duration-release</code>）</td><td>scale 0.97 → 1，底回到 hover / rest</td><td><code>--xh-motion-ease-release</code></td></tr></tbody></table><ul><li>transform origin 固定居中；指针 <code>:active</code>、键盘 Space / Enter 与 Headless 投影的 <code>data-pressed</code> 三者一致。</li><li>行级条目与 disclosure trigger（菜单项、树节点、表格行、手风琴标题）只换面，不缩放整个条目；不允许零反馈。</li><li>不用点击波纹；不允许组件自设 0.94 / 0.96 / 0.98 等缩放。</li><li>业务事件不等动画结束：按下首帧先于异步 loading 可见；pending 后锁定重复操作，不持续缩放。</li><li>hover + pressed 时 pressed 优先；focus-visible + pressed 保留焦点环、按压只改内部表面；selected / danger + pressed 保留各自身份，在其上派生 active 面。</li></ul><h2 id="披露" tabindex="-1">披露 <a class="header-anchor" href="#披露" aria-label="Permalink to &quot;披露&quot;">​</a></h2><ul><li>Surface 级展开（Accordion、Collapsible、Reasoning、ToolCall）内容走 <code>grid-template-rows: 0fr → 1fr</code>：展开 <code>--xh-motion-duration-expand</code> + <code>--xh-motion-ease-enter-strong</code>，收起 <code>--xh-motion-duration-collapse</code> + <code>--xh-motion-ease-exit</code>；指示器随内容同档转向，减弱动效下两者都瞬时完成。</li><li>密集展开（Tree、TreeSelect、JsonViewer、SideNav 内联子层、Table 展开行、Truncate）不动高度，刻意瞬时；树族只旋转指示器 <code>--xh-motion-duration-nudge</code>。</li><li>初始即展开的内容直接呈现，不播展开动画。</li></ul><h2 id="浮层进出场" tabindex="-1">浮层进出场 <a class="header-anchor" href="#浮层进出场" aria-label="Permalink to &quot;浮层进出场&quot;">​</a></h2><p>按锚定关系与面的类型分组，关键帧集中在 <code>family/motion.css</code>，皮肤不得重定义：</p><table tabindex="0"><thead><tr><th>关系</th><th>关键帧</th><th>组件</th></tr></thead><tbody><tr><td>锚定列表 / 菜单</td><td><code>xh-overlay-slide-in / out</code></td><td>Menu、Select、Combobox、Cascader、ContextMenu、Menubar、Mention、TreeSelect、Date / Time picker、ColorPicker、Tooltip</td></tr><tr><td>锚定面板</td><td><code>xh-overlay-pop-in</code> / <code>xh-pop-out</code></td><td>Popover、HoverCard、Popconfirm、Tour、Command</td></tr><tr><td>无锚定弹出</td><td><code>xh-pop-in / out</code></td><td>NavigationMenu、SideNav popout、FloatingPanel、FloatButton 列表、Pagination 弹层、BackTop、Log / MessageFeed 回底按钮</td></tr><tr><td>面板（sheet）</td><td><code>xh-sheet-in / out</code></td><td>Dialog、Notification</td></tr><tr><td>整幅滑入</td><td><code>xh-slide-in / out</code></td><td>Drawer、Layout 抽屉式侧栏：入场 <code>slide</code> + <code>ease-slide</code>，退场 <code>exit</code> + <code>ease-exit</code></td></tr></tbody></table><p>遮罩与全屏面 <code>xh-fade-in / out</code>。有进场就有退场：退场一律经 Presence 等浏览器实际起播的退场动画播完再卸载或藏起，不用固定计时器；常挂的部件（回到顶部、回到底部）收起时先播完退场再带上 <code>hidden</code>。</p><h2 id="列表" tabindex="-1">列表 <a class="header-anchor" href="#列表" aria-label="Permalink to &quot;列表&quot;">​</a></h2><ul><li>加入用 <code>xh-item-in</code>（淡入 + <code>distance-md</code> 上移），移除用 <code>xh-fade-out</code>；重排用 FLIP：读取旧位置、写入新布局、以 <code>translate</code> 反向补偿后过渡到 0，<code>move</code> + <code>continuous</code>。</li><li>条目由作者渲染、删掉即卸载的集合（TagsInput、FieldArray）由列表动效原语 <code>trackListMotion</code> 接住离场：在原位置放一个退场态的替身，绝对定位在原排布位、不可交互，播完即移除；留下来的条目从旧位置滑到新位置。作者的列表写法不变。</li><li>启用列表增删动效的集合：TagsInput、FieldArray，以及 Toast、Notification、MessageFeed、Command、Cascader；Transfer（两侧同时变化）与 InfiniteScroll（批量追加）不启用。</li></ul><h2 id="数值与指示" tabindex="-1">数值与指示 <a class="header-anchor" href="#数值与指示" aria-label="Permalink to &quot;数值与指示&quot;">​</a></h2><ul><li>进度类填充（Progress、LoadingBar、FileUpload 进度）不动 <code>inline-size</code>：填充铺满轨道、按比例 <code>translate</code>，由轨道裁掉，只走合成。倒计时条自己就是填充，用 <code>clip-path</code> 裁切收起；减弱动效下按秒分段。</li><li>不定进度以固定宽度的一段做 <code>translate</code> 往复。</li><li>数值补间（NumberAnimation）的时长由属性给出，减弱动效下直接落到终值。</li><li>滑动指示器（Tabs、Segmented、Anchor、NavigationMenu）取当前项相对列表容器的 <code>offset*</code> 排布位：不用 <code>getBoundingClientRect</code>，祖先的进场缩放会让测量值失真。位置用 <code>translate</code>，尺寸用 <code>inline-size</code> / <code>block-size</code>。Tabs 的标签带滚动已经占了 <code>translate</code>，指示条的位置叠在 <code>transform</code> 上，两者互不覆盖。</li></ul><h2 id="布局动画例外与-will-change" tabindex="-1">布局动画例外与 will-change <a class="header-anchor" href="#布局动画例外与-will-change" aria-label="Permalink to &quot;布局动画例外与 will-change&quot;">​</a></h2><p>优先动可合成的属性：<code>translate</code>、<code>scale</code>、<code>rotate</code>、<code>opacity</code>；<code>clip-path</code> 只触发重绘，可以使用。动布局属性只允许这几处：</p><table tabindex="0"><thead><tr><th>例外</th><th>理由</th></tr></thead><tbody><tr><td>披露内容 <code>grid-template-rows</code> 与内缩</td><td>唯一可行的内容高度过渡</td></tr><tr><td>指示器的 <code>inline-size</code> / <code>block-size</code></td><td>绝对定位的独立小元素，不影响其他元素</td></tr><tr><td>Switch 滑块按下伸长、Carousel 当前指示点伸长</td><td>部件很小，影响范围只有自己</td></tr><tr><td>Layout 侧栏折叠</td><td>必须让出内容区宽度</td></tr><tr><td>QuestionFlow 视口高度、Toast 堆叠高度</td><td>容器必须随内容增减高度</td></tr><tr><td>Tour 聚光框的位置与尺寸、进度点伸长</td><td>聚光框是 <code>position: fixed</code> 的独立框，不在文档流里；进度点只有几像素</td></tr></tbody></table><p>新增一处布局动画，要么改成可合成的写法，要么把理由登记进门禁 <code>check-motion-layout</code> 的例外表。</p><p><code>will-change</code> 只写在正在动的状态下：拖拽中（<code>data-dragging</code>）、机器驱动的补间进行中（<code>data-animating</code>），以及 Presence 管理的部件的收起态（<code>data-state=&quot;closed&quot;</code>，只在退场那一段留在屏上）。常驻的 <code>will-change</code> 一直占着合成层，静止画面的文字与 1px 分隔线会发虚；不可合成的属性不写 <code>will-change</code>。</p><h2 id="书写" tabindex="-1">书写 <a class="header-anchor" href="#书写" aria-label="Permalink to &quot;书写&quot;">​</a></h2><p>transition 列表写长名：<code>background-color</code>、<code>border-color</code>、<code>outline-color</code>、<code>box-shadow</code>、<code>opacity</code>、<code>translate</code>、<code>scale</code>、<code>rotate</code>，不写 <code>background</code>、<code>border</code>、<code>outline</code> 与 <code>transform</code> 简写（门禁 <code>check-motion-role</code>）。位置、旋转与缩放用独立的 <code>translate</code> / <code>rotate</code> / <code>scale</code>，连接层内联写的位移也一样；只有独立属性表达不了的组合才写 <code>transform</code> 并登记理由——现在只有 Tabs 的指示条：标签带滚动已经占了 <code>translate</code>，指示条的位置叠在 <code>transform</code> 上。不写 <code>transition: all</code>。</p><h2 id="弹簧与-js-动画" tabindex="-1">弹簧与 JS 动画 <a class="header-anchor" href="#弹簧与-js-动画" aria-label="Permalink to &quot;弹簧与 JS 动画&quot;">​</a></h2><ul><li>手势松手（Carousel 翻页、Sortable 放下、ImageViewer 平移惯性、Switch 拖动拇指）用 <code>@xihan-ui/motion</code> 的弹簧，交接松手速度；liquid 档的切换与指示也用弹簧。其余角色用曲线：出现与披露经 Presence 等待动画结束，弹簧没有确定的结束时间；数值必须精确落在终值。</li><li>JS 动效只经 <code>@xihan-ui/motion</code>：不直接排帧循环，不写固定毫秒；时长与缓动从元素读取令牌（<code>readMotion</code>），判断减弱动效传入组件自己的元素（<code>resolveMotionPreference(el)</code>）。适配器中不写动画代码。</li><li><code>animate()</code> 缺省取 <code>durations.normal</code>，<code>@xihan-ui/animations</code> 的配方缺省取 <code>slide</code>。见 <a href="/guide/motion">动效原语</a> 与 <a href="/guide/animations">动画层</a>。</li></ul><h2 id="减弱动效" tabindex="-1">减弱动效 <a class="header-anchor" href="#减弱动效" aria-label="Permalink to &quot;减弱动效&quot;">​</a></h2><p><code>data-motion=&quot;reduce&quot;</code>（偏好 <code>system</code> 时跟 <code>prefers-reduced-motion</code>）去掉位移、保留淡变：位移、缩放、旋转与尺寸变化瞬时完成（几何类时长为 1ms，位移与整幅位移归零，缩放归 1，错开步长归 0），换色与出现的淡变保留为 120ms（<code>micro</code> / <code>enter</code> / <code>exit</code>）。按下仍然换底，浮层仍然淡入淡出、退场照样等 120ms 的淡出播完再卸载，只是不再滑动与缩放；抽屉与覆盖式侧栏改为淡入淡出；循环动画停止并显示静态替代；<code>@xihan-ui/animations</code> 的预设不播。</p><p><code>data-motion=&quot;default&quot;</code> 恢复完整动效：系统要求减弱、而产品设置或某个局部容器选择完整动效时，该子树的令牌回到基线取值。两者可以嵌套，最近的一层生效。JS 侧经 <code>resolveMotionPreference(el)</code> 按元素读同一个答案——Presence、贴底滚动、平滑滚动、数字动画、轮播起播、背景层全部走这一条通道；产品自己的「减弱动效」设置用 <code>setMotionOverride</code> 一处设置、处处生效。</p><p>提示延迟、自动播放间隔、轻提示停留这类等待不是动效，不受减弱动效影响，见 <a href="/design/dwell">停留时长</a>；自动播放是例外，减弱动效下不自动起播。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/design/dwell">停留时长</a> · <a href="/design/shadow">阴影与材质</a> · <a href="/design/patterns">组件家族与模式</a></li><li>指南：<a href="/guide/motion">动效原语</a> · <a href="/guide/animations">动画层</a> · <a href="/guide/theme#点击触感">设计令牌与主题 · 点击触感</a></li></ul>',34))])}const b=c(n,[["render",l]]);export{p as __pageData,b as default};
